// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const elements = $json.elements || [];

return elements.map(place => {
  const tags = place.tags || {};

  return {
    json: {
      name: tags.name || "Unknown",
      category:
        tags.tourism ||
        tags.historic ||
        tags.leisure ||
        "attraction",
      latitude: place.lat ?? place.center?.lat,
      longitude: place.lon ?? place.center?.lon,
      city: tags["addr:city"] || "Chennai"
    }
  };
});

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const items = $input.all();

return items
  .filter(item => item.json.tags?.name)
  .map(item => {
    const place = item.json;
    const tags = place.tags || {};

    return {
      json: {
        name: tags.name || "Unknown",

        cuisine: tags.cuisine || "Unknown",

        type: tags.amenity || "Unknown",

        latitude: place.lat ?? place.center?.lat,
        longitude: place.lon ?? place.center?.lon,

        address: [
          tags["addr:housenumber"],
          tags["addr:street"],
          tags["addr:city"]
        ]
          .filter(Boolean)
          .join(", "),

        opening_hours: tags.opening_hours || "Not available",

        phone: tags.phone || "Not available",

        website: tags.website || "Not available",

        vegetarian: tags["diet:vegetarian"] || "unknown",

        vegan: tags["diet:vegan"] || "unknown",

        takeaway: tags.takeaway || "unknown",

        outdoor_seating: tags.outdoor_seating || "unknown",

        wheelchair: tags.wheelchair || "unknown",

        city: tags["addr:city"] || "Chennai"
      }
    };
  });

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const items = $input.all();

// Separate weather from places
const weatherItem = items.find(item => item.json.current);
const places = items.filter(item => !item.json.current);

// Get weather data
const weather = weatherItem?.json || {};
const current = weather.current || {};

const temperature = current.temperature_2m ?? 30;
const precipitation = current.precipitation ?? 0;
const weatherCode = current.weather_code ?? 0;

// User preference
const user = $('User preferences').first().json;

const foodPreference = (
  user.food_preference || "vegetarian"
).toLowerCase();

return places.map(item => {

  const data = item.json;

  // -------------------------
  // 1. Cuisine Score
  // -------------------------
  let cuisineScore = 0.5;

  if (data.cuisine) {
    const cuisine = data.cuisine.toLowerCase();

    if (cuisine.includes(foodPreference)) {
      cuisineScore = 1;
    } else if (
      foodPreference === "vegetarian" &&
      (cuisine.includes("indian") ||
       cuisine.includes("veg"))
    ) {
      cuisineScore = 0.8;
    } else {
      cuisineScore = 0.3;
    }
  }

  // -------------------------
  // 2. Distance
  // -------------------------
  const lat = data.latitude ?? 13.0827;
  const lon = data.longitude ?? 80.2707;

  const distance =
    Math.sqrt(
      Math.pow(lat - 13.0827, 2) +
      Math.pow(lon - 80.2707, 2)
    ) * 111;

  const distanceScore = Math.max(
    0,
    1 - distance / 5
  );

  // -------------------------
  // 3. Weather Score
  // -------------------------
  let weatherScore = 1;

  // Rain → outdoor places become less suitable
  if (precipitation > 0) {
    weatherScore = 0.4;
  }

  // Very hot → slightly lower suitability
  if (temperature > 35) {
    weatherScore = 0.6;
  }

  // -------------------------
  // 4. Place Type Score
  // -------------------------
  let typeScore = 0.5;

  if (data.type === "restaurant") {
    typeScore = 1;
  } else if (data.category === "museum") {
    typeScore = 0.9;
  } else if (data.category === "attraction") {
    typeScore = 0.8;
  } else if (data.category === "park") {
    typeScore = 0.7;
  }

  return {
    json: {
      ...data,

      distance_km: Number(distance.toFixed(2)),

      cuisine_score: Number(cuisineScore.toFixed(2)),

      distance_score: Number(distanceScore.toFixed(2)),

      weather_score: Number(weatherScore.toFixed(2)),

      type_score: Number(typeScore.toFixed(2)),

      temperature: temperature,

      precipitation: precipitation,

      weather_code: weatherCode
    }
  };
});

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const items = $input.all();

const user = $('User preferences').first().json;

const foodPreference =
  (user.food_preference || "vegetarian").toLowerCase();

const travelStyle =
  (user.travel_style || "culture_and_food").toLowerCase();

return items.map(item => {
  const data = item.json;

  const cuisine = (data.cuisine || "").toLowerCase();
  const category = (data.category || "").toLowerCase();
  const type = (data.type || "").toLowerCase();

  // -------------------------
  // DISTANCE SCORE
  // -------------------------
  const distanceScore = data.distance_score ?? 0.5;

  // -------------------------
  // WEATHER SCORE
  // -------------------------
  const weatherScore = data.weather_score ?? 0.5;

  // -------------------------
  // RESTAURANT SCORE
  // -------------------------
  let restaurantScore = 0;

  if (type === "restaurant" || type === "cafe" || type === "fast_food") {

    let cuisineScore = 0.5;

    if (cuisine.includes(foodPreference)) {
      cuisineScore = 1;
    }

    if (
      foodPreference === "vegetarian" &&
      (
        cuisine.includes("indian") ||
        data.vegetarian === "only"
      )
    ) {
      cuisineScore = 1;
    }

    let dietaryScore = 0.5;

    if (foodPreference === "vegetarian") {
      if (data.vegetarian === "only" ||
          data.vegetarian === "yes") {
        dietaryScore = 1;
      }
    }

    if (foodPreference === "vegan") {
      if (data.vegan === "only" ||
          data.vegan === "yes") {
        dietaryScore = 1;
      }
    }

    restaurantScore =
      (cuisineScore * 0.40) +
      (dietaryScore * 0.25) +
      (distanceScore * 0.20) +
      (weatherScore * 0.15);

    return {
      json: {
        ...data,
        place_kind: "restaurant",
        cuisine_score: Number(cuisineScore.toFixed(2)),
        dietary_score: Number(dietaryScore.toFixed(2)),
        recommendation_score:
          Number(restaurantScore.toFixed(3))
      }
    };
  }

  // -------------------------
  // ATTRACTION SCORE
  // -------------------------

  let categoryScore = 0.5;

  if (
    travelStyle.includes("culture") &&
    (
      category.includes("museum") ||
      category.includes("historic")
    )
  ) {
    categoryScore = 1;
  }

  if (
    travelStyle.includes("nature") &&
    category.includes("park")
  ) {
    categoryScore = 1;
  }

  if (category.includes("attraction")) {
    categoryScore = 0.8;
  }

  const attractionScore =
    (categoryScore * 0.40) +
    (distanceScore * 0.35) +
    (weatherScore * 0.25);

  return {
    json: {
      ...data,
      place_kind: "attraction",
      category_score: Number(categoryScore.toFixed(2)),
      recommendation_score:
        Number(attractionScore.toFixed(3))
    }
  };
});

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const items = $input.all();

const restaurants = items
  .filter(item => item.json.place_kind === "restaurant")
  .slice(0, 5);

const attractions = items
  .filter(item => item.json.place_kind === "attraction")
  .slice(0, 5);

return [...restaurants, ...attractions];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const items = $input.all();

const restaurants = items
  .filter(item => item.json.place_kind === "restaurant")
  .map(item => item.json);

const attractions = items
  .filter(item => item.json.place_kind === "attraction")
  .map(item => item.json);

const user = $('User preferences').first().json;

return [
  {
    json: {
      user_preferences: user,
      restaurants,
      attractions
    }
  }
];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const output = $json.output || "";

return [
  {
    json: {
      itinerary: output
    }
  }
];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const data = $json;

const user = data.user_preferences || {};

const budget = Number(user.budget || 0);
const days = Number(user.days || 1);

const dailyBudget = budget / days;

return [
  {
    json: {
      ...data,

      budget_info: {
        total_budget: budget,
        days: days,
        daily_budget: Number(dailyBudget.toFixed(2)),
        breakfast_budget: Number((dailyBudget * 0.20).toFixed(2)),
        lunch_budget: Number((dailyBudget * 0.30).toFixed(2)),
        dinner_budget: Number((dailyBudget * 0.30).toFixed(2)),
        activities_budget: Number((dailyBudget * 0.20).toFixed(2))
      }
    }
  }
];

// Safely parse JSON output from Format Final Output node
let itinerary = {};
try {
  itinerary = typeof $json.itinerary === 'string' 
    ? JSON.parse($json.itinerary) 
    : ($json.itinerary || {});
} catch (e) {
  itinerary = $json.itinerary || {};
}

// Extract first day data safely
const dayData = (itinerary.days && itinerary.days[0]) ? itinerary.days[0] : {};

return [
  {
    json: {
      city: itinerary.city || "",
      trip_title: itinerary.trip_title || "",
      day: dayData.day || 1,
      day_title: dayData.title || "",
      total_budget: itinerary.total_budget || 0,
      budget_note: itinerary.budget_note || "",
      weather_summary: itinerary.weather_summary || "",

      // Location Names
      breakfast: dayData.breakfast?.name || "",
      morning_attraction: dayData.morning_attraction?.name || "",
      lunch: dayData.lunch?.name || "",
      evening_attraction: dayData.evening_attraction?.name || "",
      dinner: dayData.dinner?.name || "",

      // Location Times
      breakfast_time: dayData.breakfast?.time || "",
      morning_attraction_time: dayData.morning_attraction?.time || "",
      lunch_time: dayData.lunch?.time || "",
      evening_attraction_time: dayData.evening_attraction?.time || "",
      dinner_time: dayData.dinner?.time || ""
    }
  }
];
